+
+const (
+	shapeKindPolygon     uint8 = 1
+	shapeKindPolyline    uint8 = 2
+	shapeKindPointVector uint8 = 3
+	shapeKindLaxPolyline uint8 = 4
+	shapeKindLaxPolygon  uint8 = 5
+	shapeKindLoop        uint8 = 6
+	shapeKindLaxLoop     uint8 = 7
+	shapeKindGeneric     uint8 = 8
+
+	maxEncodedIndexEdgesPerCell = 10000
+	maxEncodedIndexShapes       = 1000000
+	maxEncodedIndexLoops        = 1000000
+	maxEncodedIndexVertices     = 1000000
+	maxEncodedIndexTotalVerts   = 10000000
+	maxEncodedIndexCells        = 1000000
+	maxInitialSliceAlloc        = 1024
+)
+
+// genericShape is a fallback Shape implementation used when decoding a Shape
+// that does not correspond to one of the concrete exported Shape types.
+type genericShape struct {
+	dimension int
+	tag       typeTag
+	refPoint  ReferencePoint
+	isEmpty   bool
+	isFull    bool
+	chains    []Chain
+	edges     []Edge
+}
+
+func (g *genericShape) NumEdges() int                  { return len(g.edges) }
+func (g *genericShape) Edge(i int) Edge                { return g.edges[i] }
+func (g *genericShape) ReferencePoint() ReferencePoint { return g.refPoint }
+func (g *genericShape) NumChains() int                 { return len(g.chains) }
+func (g *genericShape) Chain(chainID int) Chain        { return g.chains[chainID] }
+func (g *genericShape) ChainEdge(chainID, offset int) Edge {
+	return g.edges[g.chains[chainID].Start+offset]
+}
+func (g *genericShape) ChainPosition(edgeID int) ChainPosition {
+	for i, c := range g.chains {
+		if edgeID >= c.Start && edgeID < c.Start+c.Length {
+			return ChainPosition{i, edgeID - c.Start}
+		}
+	}
+	return ChainPosition{0, edgeID}
+}
+func (g *genericShape) Dimension() int    { return g.dimension }
+func (g *genericShape) IsEmpty() bool     { return g.isEmpty }
+func (g *genericShape) IsFull() bool      { return g.isFull }
+func (g *genericShape) typeTag() typeTag  { return g.tag }
+func (g *genericShape) privateInterface() {}
+
+// Encode encodes the ShapeIndex to the given writer.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	if s == nil {
+		return errors.New("s2: cannot encode nil ShapeIndex")
+	}
+	if w == nil {
+		return errors.New("s2: cannot encode ShapeIndex to nil writer")
+	}
+	s.Build()
+
+	crc := crc32.NewIEEE()
+	e := &encoder{w: io.MultiWriter(w, crc)}
+	s.encode(e)
+	if e.err != nil {
+		return e.err
+	}
+
+	var crcBuf [4]byte
+	binary.LittleEndian.PutUint32(crcBuf[:], crc.Sum32())
+	_, err := w.Write(crcBuf[:])
+	return err
+}
+
+func (s *ShapeIndex) encode(e *encoder) {
+	e.writeInt8(encodingVersion)
+
+	maxEdges := s.maxEdgesPerCell
+	if maxEdges <= 0 {
+		maxEdges = 10
+	}
+	e.writeUint32(uint32(maxEdges))
+
+	shapeIDs := make([]int32, 0, len(s.shapes))
+	nextID := s.nextID
+	for id, shape := range s.shapes {
+		if shape == nil {
+			continue
+		}
+		if id < 0 {
+			e.err = fmt.Errorf("s2: negative shape ID %d", id)
+			return
+		}
+		shapeIDs = append(shapeIDs, id)
+		if id >= nextID {
+			nextID = id + 1
+		}
+	}
+	if nextID < 0 {
+		nextID = 0
+	}
+	slices.Sort(shapeIDs)
+
+	e.writeUint32(uint32(nextID))
+	e.writeUint32(uint32(len(shapeIDs)))
+	for _, id := range shapeIDs {
+		e.writeUint32(uint32(id))
+		encodeIndexShape(e, s.shapes[id])
+		if e.err != nil {
+			return
+		}
+	}
+
+	cells := s.cells
+	if len(cells) != len(s.cellMap) {
+		cells = make([]CellID, 0, len(s.cellMap))
+		for cid := range s.cellMap {
+			cells = append(cells, cid)
+		}
+		slices.Sort(cells)
+	}
+
+	e.writeUint32(uint32(len(cells)))
+	for _, cid := range cells {
+		e.writeUint64(uint64(cid))
+		cell := s.cellMap[cid]
+		if cell == nil {
+			e.writeUint32(0)
+			continue
+		}
+		e.writeUint32(uint32(len(cell.shapes)))
+		for _, cs := range cell.shapes {
+			e.writeUint32(uint32(cs.shapeID))
+			e.writeBool(cs.containsCenter)
+			e.writeUint32(uint32(len(cs.edges)))
+			for _, edgeID := range cs.edges {
+				e.writeUint32(uint32(edgeID))
+			}
+		}
+	}
+}
+
+func encodeIndexPoint(e *encoder, pt Point) {
+	e.writeFloat64(pt.X)
+	e.writeFloat64(pt.Y)
+	e.writeFloat64(pt.Z)
+}
+
+func encodeIndexPoints(e *encoder, pts []Point) {
+	e.writeBool(pts == nil)
+	e.writeUint32(uint32(len(pts)))
+	for _, pt := range pts {
+		encodeIndexPoint(e, pt)
+	}
+}
+
+func encodeIndexLoop(e *encoder, l *Loop) {
+	encodeIndexPoints(e, l.vertices)
+	e.writeBool(l.originInside)
+	e.writeInt32(int32(l.depth))
+	l.bound.encode(e)
+	l.subregionBound.encode(e)
+	e.writeBool(l.index != nil)
+}
+
+func encodeIndexShape(e *encoder, shape Shape) {
+	switch sh := shape.(type) {
+	case *Polygon:
+		e.writeUint8(shapeKindPolygon)
+		e.writeBool(sh.hasHoles)
+		e.writeUint32(uint32(len(sh.loops)))
+		for _, l := range sh.loops {
+			encodeIndexLoop(e, l)
+		}
+		sh.bound.encode(e)
+		sh.subregionBound.encode(e)
+		e.writeBool(sh.index != nil)
+
+	case *Polyline:
+		e.writeUint8(shapeKindPolyline)
+		encodeIndexPoints(e, *sh)
+
+	case *PointVector:
+		e.writeUint8(shapeKindPointVector)
+		encodeIndexPoints(e, *sh)
+
+	case *LaxPolyline:
+		e.writeUint8(shapeKindLaxPolyline)
+		encodeIndexPoints(e, sh.vertices)
+
+	case *LaxPolygon:
+		e.writeUint8(shapeKindLaxPolygon)
+		e.writeUint32(uint32(sh.numLoops))
+		for i := 0; i < sh.numLoops; i++ {
+			n := sh.numLoopVertices(i)
+			e.writeUint32(uint32(n))
+			for j := 0; j < n; j++ {
+				encodeIndexPoint(e, sh.loopVertex(i, j))
+			}
+		}
+
+	case *Loop:
+		e.writeUint8(shapeKindLoop)
+		encodeIndexLoop(e, sh)
+
+	case *LaxLoop:
+		e.writeUint8(shapeKindLaxLoop)
+		encodeIndexPoints(e, sh.vertices)
+
+	default:
+		e.writeUint8(shapeKindGeneric)
+		e.writeUint8(uint8(sh.Dimension()))
+		e.writeUint32(uint32(sh.typeTag()))
+		ref := sh.ReferencePoint()
+		e.writeBool(ref.Contained)
+		encodeIndexPoint(e, ref.Point)
+		e.writeBool(sh.IsEmpty())
+		e.writeBool(sh.IsFull())
+		numChains := sh.NumChains()
+		e.writeUint32(uint32(numChains))
+		for c := 0; c < numChains; c++ {
+			ch := sh.Chain(c)
+			e.writeUint32(uint32(ch.Start))
+			e.writeUint32(uint32(ch.Length))
+		}
+		numEdges := sh.NumEdges()
+		e.writeUint32(uint32(numEdges))
+		for i := 0; i < numEdges; i++ {
+			edge := sh.Edge(i)
+			encodeIndexPoint(e, edge.V0)
+			encodeIndexPoint(e, edge.V1)
+		}
+	}
+}
+
+type crcByteReader struct {
+	r   byteReader
+	crc hash.Hash32
+}
+
+func (c *crcByteReader) Read(p []byte) (int, error) {
+	n, err := c.r.Read(p)
+	if n > 0 {
+		_, _ = c.crc.Write(p[:n])
+	}
+	return n, err
+}
+
+func (c *crcByteReader) ReadByte() (byte, error) {
+	b, err := c.r.ReadByte()
+	if err == nil {
+		_, _ = c.crc.Write([]byte{b})
+	}
+	return b, err
+}
+
+type shapeIndexDecoder struct {
+	decoder
+	totalVerts uint64
+}
+
+func (d *shapeIndexDecoder) readStrictBool() bool {
+	if d.err != nil {
+		return false
+	}
+	b := d.readUint8()
+	if d.err != nil {
+		return false
+	}
+	if b > 1 {
+		d.err = fmt.Errorf("s2: invalid bool value %d", b)
+		return false
+	}
+	return b == 1
+}
+
+func (d *shapeIndexDecoder) readFiniteFloat64() float64 {
+	v := d.readFloat64()
+	if d.err != nil {
+		return 0
+	}
+	if math.IsNaN(v) || math.IsInf(v, 0) {
+		d.err = errors.New("s2: invalid float64 (NaN or Inf)")
+		return 0
+	}
+	return v
+}
+
+func (d *shapeIndexDecoder) readPoint() Point {
+	x := d.readFiniteFloat64()
+	y := d.readFiniteFloat64()
+	z := d.readFiniteFloat64()
+	return Point{r3.Vector{X: x, Y: y, Z: z}}
+}
+
+func (d *shapeIndexDecoder) readRawPoints(n uint32) []Point {
+	if d.err != nil {
+		return nil
+	}
+	if n > maxEncodedIndexVertices || d.totalVerts+uint64(n) > maxEncodedIndexTotalVerts {
+		d.err = fmt.Errorf("s2: too many vertices (%d)", n)
+		return nil
+	}
+	d.totalVerts += uint64(n)
+	pts := make([]Point, 0, min(int(n), maxInitialSliceAlloc))
+	for range n {
+		pt := d.readPoint()
+		if d.err != nil {
+			return nil
+		}
+		pts = append(pts, pt)
+	}
+	return pts
+}
+
+func (d *shapeIndexDecoder) readPoints() []Point {
+	isNil := d.readStrictBool()
+	n := d.readUint32()
+	if d.err != nil {
+		return nil
+	}
+	if isNil && n != 0 {
+		d.err = errors.New("s2: non-zero count for nil slice")
+		return nil
+	}
+	pts := d.readRawPoints(n)
+	if d.err != nil {
+		return nil
+	}
+	if isNil {
+		return nil
+	}
+	return pts
+}
+
+func (d *shapeIndexDecoder) readRect() Rect {
+	var r Rect
+	if d.err != nil {
+		return r
+	}
+	if version := d.readUint8(); int8(version) != encodingVersion {
+		if d.err == nil {
+			d.err = fmt.Errorf("s2: unsupported Rect version %d", version)
+		}
+		return r
+	}
+	r.Lat.Lo = d.readFiniteFloat64()
+	r.Lat.Hi = d.readFiniteFloat64()
+	r.Lng.Lo = d.readFiniteFloat64()
+	r.Lng.Hi = d.readFiniteFloat64()
+	return r
+}
+
+func (d *shapeIndexDecoder) decodeLoop() *Loop {
+	pts := d.readPoints()
+	originInside := d.readStrictBool()
+	depth := int32(d.readUint32())
+	if d.err != nil {
+		return nil
+	}
+	if depth < 0 || depth > maxEncodedIndexLoops {
+		d.err = fmt.Errorf("s2: invalid loop depth %d", depth)
+		return nil
+	}
+	bound := d.readRect()
+	subregionBound := d.readRect()
+	hasIndex := d.readStrictBool()
+	if d.err != nil {
+		return nil
+	}
+	l := &Loop{
+		vertices:       pts,
+		originInside:   originInside,
+		depth:          int(depth),
+		bound:          bound,
+		subregionBound: subregionBound,
+	}
+	if hasIndex {
+		l.index = NewShapeIndex()
+		l.index.Add(l)
+	}
+	return l
+}
+
+func (d *shapeIndexDecoder) decodeShape() Shape {
+	kind := d.readUint8()
+	if d.err != nil {
+		return nil
+	}
+	switch kind {
+	case shapeKindPolygon:
+		hasHoles := d.readStrictBool()
+		nloops := d.readUint32()
+		if d.err != nil {
+			return nil
+		}
+		if nloops > maxEncodedIndexLoops {
+			d.err = fmt.Errorf("s2: too many loops in Polygon (%d)", nloops)
+			return nil
+		}
+		loops := make([]*Loop, 0, min(int(nloops), maxInitialSliceAlloc))
+		for range nloops {
+			l := d.decodeLoop()
+			if d.err != nil {
+				return nil
+			}
+			loops = append(loops, l)
+		}
+		bound := d.readRect()
+		subregionBound := d.readRect()
+		hasIndex := d.readStrictBool()
+		if d.err != nil {
+			return nil
+		}
+		p := &Polygon{
+			loops:          loops,
+			hasHoles:       hasHoles,
+			bound:          bound,
+			subregionBound: subregionBound,
+		}
+		for _, l := range p.loops {
+			p.numVertices += len(l.vertices)
+		}
+		p.initEdgesAndIndex()
+		if !hasIndex {
+			p.index = nil
+			if nloops == 0 {
+				p.loops = nil
+			}
+		}
+		return p
+
+	case shapeKindPolyline:
+		pts := d.readPoints()
+		if d.err != nil {
+			return nil
+		}
+		pl := Polyline(pts)
+		return &pl
+
+	case shapeKindPointVector:
+		pts := d.readPoints()
+		if d.err != nil {
+			return nil
+		}
+		pv := PointVector(pts)
+		return &pv
+
+	case shapeKindLaxPolyline:
+		pts := d.readPoints()
+		if d.err != nil {
+			return nil
+		}
+		return &LaxPolyline{vertices: pts}
+
+	case shapeKindLaxPolygon:
+		nloops := d.readUint32()
+		if d.err != nil {
+			return nil
+		}
+		if nloops > maxEncodedIndexLoops {
+			d.err = fmt.Errorf("s2: too many loops in LaxPolygon (%d)", nloops)
+			return nil
+		}
+		loops := make([][]Point, 0, min(int(nloops), maxInitialSliceAlloc))
+		for range nloops {
+			nverts := d.readUint32()
+			pts := d.readRawPoints(nverts)
+			if d.err != nil {
+				return nil
+			}
+			loops = append(loops, pts)
+		}
+		return LaxPolygonFromPoints(loops)
+
+	case shapeKindLoop:
+		l := d.decodeLoop()
+		if d.err != nil {
+			return nil
+		}
+		return l
+
+	case shapeKindLaxLoop:
+		pts := d.readPoints()
+		if d.err != nil {
+			return nil
+		}
+		return &LaxLoop{
+			numVertices: len(pts),
+			vertices:    pts,
+		}
+
+	case shapeKindGeneric:
+		dim := d.readUint8()
+		if d.err != nil {
+			return nil
+		}
+		if dim > 2 {
+			d.err = fmt.Errorf("s2: invalid shape dimension %d", dim)
+			return nil
+		}
+		tag := typeTag(d.readUint32())
+		refContained := d.readStrictBool()
+		refPoint := d.readPoint()
+		isEmpty := d.readStrictBool()
+		isFull := d.readStrictBool()
+		nchains := d.readUint32()
+		if d.err != nil {
+			return nil
+		}
+		if nchains > maxEncodedIndexVertices {
+			d.err = fmt.Errorf("s2: too many chains (%d)", nchains)
+			return nil
+		}
+		chains := make([]Chain, 0, min(int(nchains), maxInitialSliceAlloc))
+		for range nchains {
+			start := d.readUint32()
+			length := d.readUint32()
+			if d.err != nil {
+				return nil
+			}
+			if start > maxEncodedIndexVertices || length > maxEncodedIndexVertices {
+				d.err = errors.New("s2: invalid chain bounds")
+				return nil
+			}
+			chains = append(chains, Chain{Start: int(start), Length: int(length)})
+		}
+		nedges := d.readUint32()
+		if d.err != nil {
+			return nil
+		}
+		if nedges > maxEncodedIndexVertices || d.totalVerts+uint64(nedges)*2 > maxEncodedIndexTotalVerts {
+			d.err = fmt.Errorf("s2: too many edges (%d)", nedges)
+			return nil
+		}
+		d.totalVerts += uint64(nedges) * 2
+		edges := make([]Edge, 0, min(int(nedges), maxInitialSliceAlloc))
+		for range nedges {
+			v0 := d.readPoint()
+			v1 := d.readPoint()
+			if d.err != nil {
+				return nil
+			}
+			edges = append(edges, Edge{V0: v0, V1: v1})
+		}
+		for _, ch := range chains {
+			if ch.Start < 0 || ch.Length < 0 || ch.Start+ch.Length > len(edges) {
+				d.err = errors.New("s2: chain out of edge bounds")
+				return nil
+			}
+		}
+		return &genericShape{
+			dimension: int(dim),
+			tag:       tag,
+			refPoint:  ReferencePoint{Point: refPoint, Contained: refContained},
+			isEmpty:   isEmpty,
+			isFull:    isFull,
+			chains:    chains,
+			edges:     edges,
+		}
+
+	default:
+		d.err = fmt.Errorf("s2: unknown encoded shape kind %d", kind)
+		return nil
+	}
+}
+
+// Decode decodes the ShapeIndex from the given reader.
+func (s *ShapeIndex) Decode(r io.Reader) error {
+	if s == nil {
+		return errors.New("s2: cannot decode into nil ShapeIndex")
+	}
+	if r == nil {
+		return errors.New("s2: cannot decode ShapeIndex from nil reader")
+	}
+	br := asByteReader(r)
+	crc := crc32.NewIEEE()
+	cr := &crcByteReader{r: br, crc: crc}
+	d := &shapeIndexDecoder{
+		decoder: decoder{r: cr},
+	}
+	s.decode(d, crc)
+	return d.err
+}
+
+func (s *ShapeIndex) decode(d *shapeIndexDecoder, crc hash.Hash32) {
+	version := int8(d.readUint8())
+	if d.err != nil {
+		return
+	}
+	if version != encodingVersion {
+		d.err = fmt.Errorf("s2: unsupported ShapeIndex version %d", version)
+		return
+	}
+
+	maxEdgesPerCell := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if maxEdgesPerCell == 0 || maxEdgesPerCell > maxEncodedIndexEdgesPerCell {
+		d.err = fmt.Errorf("s2: invalid maxEdgesPerCell %d", maxEdgesPerCell)
+		return
+	}
+
+	nextID := d.readUint32()
+	numShapes := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if nextID > maxEncodedIndexShapes || numShapes > nextID || numShapes > maxEncodedIndexShapes {
+		d.err = fmt.Errorf("s2: invalid shape counts (nextID=%d, numShapes=%d)", nextID, numShapes)
+		return
+	}
+
+	shapes := make(map[int32]Shape, min(int(numShapes), maxInitialSliceAlloc))
+	prevShapeID := int32(-1)
+	for i := uint32(0); i < numShapes; i++ {
+		id := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if id >= nextID || (i > 0 && int32(id) <= prevShapeID) {
+			d.err = fmt.Errorf("s2: invalid shape ID %d", id)
+			return
+		}
+		prevShapeID = int32(id)
+		sh := d.decodeShape()
+		if d.err != nil {
+			return
+		}
+		shapes[int32(id)] = sh
+	}
+
+	numCells := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if numCells > maxEncodedIndexCells || (numShapes == 0 && numCells > 0) {
+		d.err = fmt.Errorf("s2: invalid cell count %d", numCells)
+		return
+	}
+
+	var cells []CellID
+	if numCells > 0 {
+		cells = make([]CellID, 0, min(int(numCells), maxInitialSliceAlloc))
+	}
+	cellMap := make(map[CellID]*ShapeIndexCell, min(int(numCells), maxInitialSliceAlloc))
+	var totalClippedEdges uint64
+
+	for i := uint32(0); i < numCells; i++ {
+		cid := CellID(d.readUint64())
+		if d.err != nil {
+			return
+		}
+		if !cid.IsValid() || (i > 0 && cid.RangeMin() <= cells[i-1].RangeMax()) {
+			d.err = fmt.Errorf("s2: invalid or out-of-order cell ID %v", cid)
+			return
+		}
+
+		numClipped := d.readUint32()
+		if d.err != nil {
+			return
+		}
+		if numClipped > numShapes || numClipped > maxEncodedIndexShapes {
+			d.err = fmt.Errorf("s2: too many clipped shapes in cell (%d)", numClipped)
+			return
+		}
+
+		clippedShapes := make([]*clippedShape, 0, min(int(numClipped), maxInitialSliceAlloc))
+		prevClippedShapeID := int32(-1)
+		for j := uint32(0); j < numClipped; j++ {
+			cShapeID := d.readUint32()
+			containsCenter := d.readStrictBool()
+			numEdges := d.readUint32()
+			if d.err != nil {
+				return
+			}
+			if cShapeID >= nextID || (j > 0 && int32(cShapeID) <= prevClippedShapeID) {
+				d.err = fmt.Errorf("s2: invalid clipped shape ID %d", cShapeID)
+				return
+			}
+			shape := shapes[int32(cShapeID)]
+			if shape == nil {
+				d.err = fmt.Errorf("s2: clipped shape references missing shape ID %d", cShapeID)
+				return
+			}
+			prevClippedShapeID = int32(cShapeID)
+
+			shapeNumEdges := uint32(shape.NumEdges())
+			if numEdges > shapeNumEdges || totalClippedEdges+uint64(numEdges) > maxEncodedIndexTotalVerts {
+				d.err = fmt.Errorf("s2: too many clipped edges (%d > %d)", numEdges, shapeNumEdges)
+				return
+			}
+			totalClippedEdges += uint64(numEdges)
+
+			edges := make([]int, 0, min(int(numEdges), maxInitialSliceAlloc))
+			prevEdgeID := -1
+			for k := uint32(0); k < numEdges; k++ {
+				edgeID := d.readUint32()
+				if d.err != nil {
+					return
+				}
+				if edgeID >= shapeNumEdges || (k > 0 && int(edgeID) <= prevEdgeID) {
+					d.err = fmt.Errorf("s2: invalid clipped edge ID %d", edgeID)
+					return
+				}
+				prevEdgeID = int(edgeID)
+				edges = append(edges, int(edgeID))
+			}
+
+			clippedShapes = append(clippedShapes, &clippedShape{
+				shapeID:        int32(cShapeID),
+				containsCenter: containsCenter,
+				edges:          edges,
+			})
+		}
+
+		cells = append(cells, cid)
+		cellMap[cid] = &ShapeIndexCell{shapes: clippedShapes}
+	}
+
+	gotCRC := crc.Sum32()
+	wantCRC := d.readUint32()
+	if d.err != nil {
+		return
+	}
+	if gotCRC != wantCRC {
+		d.err = fmt.Errorf("s2: ShapeIndex checksum mismatch: got %#08x, want %#08x", gotCRC, wantCRC)
+		return
+	}
+
+	s.mu.Lock()
+	s.maxEdgesPerCell = int(maxEdgesPerCell)
+	s.shapes = shapes
+	s.nextID = int32(nextID)
+	s.cellMap = cellMap
+	s.cells = cells
+	s.pendingAdditionsPos = int32(nextID)
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+	s.mu.Unlock()
+}
